from pathlib import Path
for f in ['exllamav3/models/gemma3.py','exllamav3/models/model.py','exllamav3/modules/conv.py','exllamav3/modules/pos_embedding.py','exllamav3/modules/transformer.py','exllamav3/modules/attn.py','exllamav3/modules/mlp.py','exllamav3/modules/layernorm.py','exllamav3/modules/rmsnorm.py','exllamav3/modules/quant/fp16.py','exllamav3/modules/quant/exl3.py']:
 lines=Path(f).read_text().splitlines()
 print(f,[(i+1,l.strip()) for i,l in enumerate(lines) if l.strip().startswith(('def forward(', 'def project_', 'def decode_flash_attn_nc(', 'def preprocess(', 'def get_image_embeddings(', 'def default_load_shape_dtype('))])
checks=0
for n in [1,2,3]:
 for p,t in [(4,2),(8,4),(64,16)]:
  k=p//t
  for b in range(n):
   for yy in range(t):
    for xx in range(t):
     offsets=[b*p*p+(yy*k+dy)*p+xx*k+dx for dy in range(k) for dx in range(k)]
     assert all(v//(p*p)==b for v in offsets)
     checks+=1
  assert (p//k)**2==t*t
print('scalar pooling index groups checked:',checks,'; every group stays in its batch item; output per image = t*t')
